from common import *
import cnn_figures
import rnn_figures
import gnn_figures
import transformer
import vit
import ssm

def build():
 body=sec('why-cnn','なぜ画像には、全結合のNNよりCNNを使うのか',
  p('<strong>CNNもニューラルネットワーク（NN）の一種です。</strong>ここでは、04・05で使った全結合のネットワーク（MLP）と比べます。MLPでも画像を分類できますが、CNNは画像の性質に合わせて接続を工夫しています。')+
  p('例えば、数字の「1」が画像の左にあっても右にあっても、縦線の形は共通です。また、線や角は、近くの画素をまとめて見ると分かります。CNNは、この<strong>「近くの画素に意味がある」「同じ模様は別の位置にも現れる」</strong>という性質を使います。')+
  cnn_figures.why_cnn()+
  sub('1. 近くの画素をまとめて見る',p('MLPの全結合層では、一つの出力が全ての入力画素につながります。画像を一列に並べても画素の値は失われませんが、どの画素が隣同士なのかを接続の仕組みでは区別しません。CNNはまず2×2や3×3などの小さな範囲を見て、線や角などの局所的な模様を調べます。層を重ねると、それらを組み合わせて広い範囲を扱えます。'))+
  sub('2. 同じ模様を、同じフィルタで探す',p('CNNは、一度学んだフィルタを左上にも右下にも使います。これが<strong>重み共有</strong>です。例えば縦線を調べるフィルタなら、画像内の各位置で縦線の有無を調べられます。MLPでは各接続の重みが独立しているため、別の位置にも同じ計算を使うという仕組みは最初から組み込まれていません。'))+
  sub('3. 学習する重みを少なくできる',p('上の図では、全結合層は16画素から9個の出力を作るため144個の重みを使います。畳み込み層は2×2の4個の重みを全位置で使い回します。画像が大きくなって計算する位置が増えても、同じフィルタの重みの数は増えません。これにより、画像の性質に合うパターンを、少ないパラメータで学びやすくなります。'))+
  p('ただし、CNNなら必ず高精度になるわけではありません。位置が変わっても画像全体の分類結果が必ず同じになるわけでもなく、データや学習の方法、画像をどう縮小するかによって性能は変わります。'))
 body+=sec('idea','CNN全体では、特徴を段階的に組み合わせる',p('畳み込みで複数の模様を調べ、poolingで縦横を小さくする処理を重ねます。最後に特徴をまとめ、画像全体の分類結果を作ります。')+cnn_figures.overview()+p('最初の層は短い境界や模様に反応し、深い層は複数の特徴を組み合わせます。ただし、全てのチャネルが人の言葉で名付けられるとは限りません。'))
 body+=sec('convolution','畳み込みの一歩：掛けて足す',img('convolution.svg','入力とフィルタから出力マップを計算する例','固定の4×4入力と2×2フィルタを使い、3×3の出力を計算。バイアス0、stride=1、padding=0。')+eq('y_{i,j,o} = b_o + \\sum_{u,v,c} K_{u,v,c,o}\\,x_{i+u,j+v,c}','Kはフィルタの重み。出力位置(i,j)で、領域内の画素と対応する重みを掛けて足す。cは入力チャネル、oは出力チャネル。深層学習で「畳み込み」と呼ぶ操作は通常、フィルタを反転しない相互相関として実装される。')+cnn_figures.demo()+p('一つの出力チャネルを作るには、入力の全チャネル分の積和を足します。3×3、入力3チャネル、出力16チャネルなら、重みは3×3×3×16個、バイアスを入れると448パラメータです。画像の縦横の大きさで重みの個数は増えません。'))
 body+=sec('shape','チャネルと受容野',p('全体図の重なった四角は、それぞれ1チャネルの特徴マップです。異なる重みのフィルタを4種類使うと4枚、8種類なら8枚の特徴マップができます。各フィルタは違う模様に反応するように学習されます。一方、poolingは各マップの縦横を小さくし、チャネル数は変えません。')+p('受容野は、ある出力の値に影響する入力画像の範囲です。3×3の畳み込みをstride=1で2層重ねると、2層目の1マスには元画像の5×5の範囲が影響します。層を重ねることで、近くの模様を組み合わせて広い範囲を扱えます。'))
 b=box(25,72,135,60,'入力 x')+box(270,72,210,60,'F(x)','畳み込みなど')+box(590,72,160,60,'F(x) + x')+line(165,102,262,102)+line(486,102,583,102)+f'<path d="M92 70V28H670V67" fill="none" stroke="{BLUE}" stroke-width="2" marker-end="url(#arrow)"/>'+txt(390,22,'残差経路：入力を足す',13,BLUE)
 body+=sec('designs','深くするResNet、細部を戻すU-Net',sub('ResNet：変化分を学ぶ',p('なぜResNetが作られたのでしょうか。通常のネットワークでは、層を増やすと表現力が増すはずなのに、訓練データに対する誤差まで悪化することがありました。ResNetはこの最適化の難しさに対し、入力をそのまま通す経路を作り、追加の層は入力からの変化分を学ぶようにしました。')+figure(svg(b,165,label='ResNetの残差接続'),'同じ形状なら入力xと変換F(x)を足せる。形状が違うときは射影でそろえる。')+p('層を増やせば自動的に学習しやすくなるわけではありません。残差接続は、入力にどの変化を加えるかを学べるようにし、深いネットワークを最適化する助けになります。'))+sub('U-Net：広い文脈と細かな位置を合わせる',p('U-Netは、少ない注釈付きの生体・医用画像から、細胞などの領域を画素単位で分けるために作られました。何が写っているかを捉えるには広い範囲が必要ですが、縮小するだけでは細かな位置が失われます。縮小側と拡大側をつなぐ構造で文脈と位置を合わせ、データ拡張も使って限られた画像を活用する設計です。')+cnn_figures.unet()+p('分類は画像全体を一つの出力へまとめますが、分割は画素ごとの出力を必要とします。U-Netでは縮小側の特徴を拡大側へ渡し、細かい境界の推定を助けます。Diffusionでは同様の構成でノイズなどを予測できます。')))
 body+=sec('training','学習と利用、得意なことと限界',p('学習では各位置に使った同じフィルタへ、すべての位置から勾配が集まります。利用時には学んだフィルタを固定して積和を計算します。分類・分割・ノイズ予測など、出力と損失を変えることで用途が広がります。')+p('局所性と重み共有は、少ないパラメータで画像を扱う助けになります。一方、遠く離れた要素の関係には層や別の仕組みが必要です。位置をずらした入力に特徴マップも対応してずれる性質（並進同変性）が基本ですが、境界処理やstrideで厳密には崩れることがあり、回転や大きさの変化に自動的に強いわけでもありません。'))
 body+=refs([('Stanford CS231n：局所接続と重み共有','https://cs231n.github.io/convolutional-networks/'),('LeCun et al., Gradient-Based Learning Applied to Document Recognition','http://yann.lecun.com/exdb/publis/pdf/lecun-98.pdf'),('ResNet（2015）','https://arxiv.org/abs/1512.03385'),('U-Net（2015）','https://arxiv.org/abs/1505.04597'),('PyTorch：Conv2dのstride・padding','https://docs.pytorch.org/docs/stable/generated/torch.nn.Conv2d.html'),('PyTorch：MaxPool2d','https://docs.pytorch.org/docs/stable/generated/torch.nn.MaxPool2d.html')])
 page('cnn','CNN — 近くの模様を積み重ねる','モデルの構造','MODEL 01 / CONVOLUTION','画像のどこにあるかが変わっても、同じ模様を同じ重みで探す。局所接続と重み共有が出発点です。',body)
 body=sec('why','なぜ、過去を引き継ぐ構造が必要なのか',p('「昨日は雨だった。今日も雨だ」と「昨日は晴れだった。今日は雨だ」では、今の「雨」は同じでも、天気が続いているのか、変わったのかが違います。今の入力だけを見て毎回独立に判断するネットワークには、この違いを伝えられません。文章や音声、センサの値のように<strong>順序と過去の情報が意味を持つデータ</strong>を、系列と呼びます。')+p('過去の入力を全部並べて通常の全結合ネットワークへ渡す方法もあります。しかし、入力欄を固定すると読める長さが決まり、長い系列を扱うほど入力も大きくなります。そこで「ここまで読んだ情報の要約」を一定サイズのベクトルとして持ち、次の入力が来るたびに更新する、という設計を考えます。')+note('構造が生まれる理由','過去を使いたい → 状態を持つ。長さが違う系列を同じ仕組みで読みたい → 同じ更新を繰り返す。この二つを組み合わせると、状態を自分の次の計算へ戻すRNNのループになる。')+p('この要約が<strong>隠れ状態 h（hidden state）</strong>です。文章そのものを保存するメモ帳ではなく、予測に役立つ情報を数値にまとめたものです。何を残すかは学習で決まります。'))
 body+=sec('state','RNN：同じ計算を繰り返し、状態を渡す',note('RNNの設計思想','過去の情報を一定サイズの状態にまとめ、今の入力と合わせて同じ計算で更新し続ける。')+p('RNN（recurrent neural network、再帰型ニューラルネットワーク）のループは、計算を同時にぐるぐる回す意味ではありません。ある時刻にできた状態を、次の時刻の入力と一緒に使う、という意味です。')+rnn_figures.unroll()+p('入力が来るたびに、①今の入力と前の状態を受け取り、②新しい状態を作り、③その状態を次へ渡します。各時刻で同じ重みを使うので、系列が長くなってもパラメータ数は増えません。出力は各時刻で作ることも、最後の状態から一つだけ作ることもできます。')+sub('1ステップの中では、何を計算するのか',rnn_figures.step())+eq('h_t = \\tanh(W_x x_t + W_h h_{t-1} + b)','xₜは時刻tの入力、hₜは更新後の状態。Wₓは入力、Wₕは前の状態を変換する行列。tanhは値を−1〜1に収める非線形関数。')+p('例えば1次元でWₓ=1、Wₕ=0.5、b=0、h₋₁=0、入力x₀, x₁が1, 0なら、h₀=tanh(1)≈0.762、h₁=tanh(0.381)≈0.363。入力が0になっても前の情報が状態に残ります。これは固定した教材用の重みで、訓練結果ではありません。'))
 body+=sec('long-memory','単純なRNNでは、遠い過去を学びにくい',p('RNNには過去を使う経路がありますが、長く保持したい情報も新しい入力と一緒に毎回変換されます。例えば、文の最初に出てきた人物の情報を、長い説明を挟んだ後でも使いたいとき、何度もの更新でその情報が変わり、取り出しにくくなることがあります。')+p('学習時には、後の予測の誤差を以前の更新へ伝えます。その途中で重みやtanhの微分が何度も掛かり、勾配が小さくなりすぎる<strong>勾配消失</strong>や、大きくなりすぎる<strong>勾配爆発</strong>が起こりえます。特に勾配消失では、「ずっと前の情報を残すべきだった」と学ぶ信号が届きにくくなります。')+note('次の設計への問い','新しい情報を計算する経路とは別に、必要な過去をそのまま運べる経路を作れないだろうか。その経路に、残す量や書き込む量を調整するゲートを付けたのがLSTMの基本的な発想。'))
 body+=sec('lstm','LSTM：記憶を運ぶ経路と、三つのゲート',note('LSTMの設計思想','記憶を運ぶセル状態を用意し、何を残し、何を書き込み、何を出力するかをゲートで選ぶ。')+p('LSTM（long short-term memory）は、隠れ状態hに加えて<strong>セル状態 c</strong>を持ちます。hはその時刻の出力に使う状態、cは情報を持ち越すための経路です。cにも毎回操作は加わりますが、過去の値に「残す割合」を掛け、新しい情報を足す形なので、必要な成分を大きく変えずに運べます。')+p('ゲートは、今の入力xと前の隠れ状態hから計算する、成分ごとの0〜1の値です。0に近いと通さず、1に近いとほぼそのまま通します。人が開閉を指定するのではなく、予測の誤差を通して各ゲートの重みを学習します。')+rnn_figures.lstm()+sub('図は、上の記憶経路から読む',bullets(['<strong>忘却ゲート f：</strong>前のセル状態cのどの成分を、どのくらい残すかを決める。','<strong>入力ゲート i と候補 g：</strong>今の入力と過去のhから候補gを作り、そのうち書き込む量をiで調整する。上の＋で、残した記憶と足し合わせる。','<strong>出力ゲート o：</strong>新しいcをtanhで変換し、今の隠れ状態hへ取り出す量を調整する。hを小さくしても、それだけでcが消えるわけではない。']))+eq('\\begin{aligned} f_t &= \\sigma(W_f[x_t;h_{t-1}] + b_f) \\\\ i_t &= \\sigma(W_i[x_t;h_{t-1}] + b_i) \\\\ o_t &= \\sigma(W_o[x_t;h_{t-1}] + b_o) \\\\ g_t &= \\tanh(W_g[x_t;h_{t-1}] + b_g) \\\\ c_t &= f_t \\odot c_{t-1} + i_t \\odot g_t \\\\ h_t &= o_t \\odot \\tanh(c_t) \\end{aligned}','[x; h]は連結、⊙は成分ごとの積。fはforget、iはinput、oはoutput、gは書き込み候補。σはsigmoid関数で、実数を0〜1へ変換する。Wとbはゲートごとに別の学習可能な重みとバイアス。')+p('1成分だけ見ると、以前のc=2、f=0.9、i=0.2、g=−1なら、新しいc=1.8−0.2=1.6です。fが1に近いと、加算の経路に過去の情報が残りやすくなります。ゲートがあるだけで無限に記憶できるわけではありません。'))
 body+=sec('gru','GRU：一つの状態を、二つのゲートで更新する',p('GRUは、機械翻訳で長さの異なる句を読み取り、別の句へ変換するRNN Encoder–Decoderの研究で提案されました。短い範囲の変化と長い範囲の依存を、一つの状態で選択的に扱うことが狙いです。過去をどれだけ使うか、どれだけ更新するかを二つのゲートで決め、LSTMより簡潔な構成で情報を保持する経路を作ります。')+note('GRUの設計思想','記憶を一つの状態にまとめ、候補に使う過去と状態を更新する割合を二つのゲートで調整する。')+p('LSTMはcとhを分けて情報の保持と取り出しを制御します。GRU（gated recurrent unit）は、この仕組みを簡素にし、<strong>独立したセル状態cを持たず、hを直接更新</strong>します。それでも、古い状態をそのまま残す経路は用意します。')+rnn_figures.gru()+bullets(['<strong>リセットゲート r（reset）：</strong>新しい候補を作るときに、過去のhをどのくらい参考にするかを決める。rが0に近い成分では、候補を主に今の入力から作る。','<strong>更新ゲート z（update）：</strong>古いhと新しい候補を混ぜる割合を決める。この図ではzが1に近いと古い状態を残し、0に近いと候補へ置き換える。'])+p('二つのゲートは役割が違います。resetを小さくして過去に頼らない候補を作っても、updateで古い状態を残すことはできます。LSTMの入力・忘却ゲートが別々の割合を出すのに対し、このGRUでは残す割合zと取り込む割合1−zが対になっています。')+eq('\\begin{aligned} r_t &= \\sigma(W_r x_t + U_r h_{t-1} + b_r) \\\\ z_t &= \\sigma(W_z x_t + U_z h_{t-1} + b_z) \\\\ \\tilde h_t &= \\tanh(Wx_t + U(r_t \\odot h_{t-1}) + b) \\\\ h_t &= z_t \\odot h_{t-1} + (1-z_t) \\odot \\tilde h_t \\end{aligned}','ここではzを「古い状態を残す割合」とする表記。文献・実装でzと1−zの役割、resetの適用位置が異なる場合がある。例えば古いh=0.8、候補=−0.2、z=0.75なら新しいh=0.55。')+table(['モデル','状態','調整の仕組み'],[('RNN','h','一つの非線形更新'),('LSTM','h と c','忘却・入力・出力のゲート'),('GRU','h','resetとupdateのゲート')]))
 body+=sec('train-use','学習と利用：時間方向にも逆伝播',p('学習では時間展開した計算をさかのぼるBPTT（backpropagation through time）で勾配を求めます。長い系列では一定区間で勾配を切る方法もあります。勾配クリッピングは大きすぎる勾配を抑える工夫ですが、失われた長期情報を復元する方法ではありません。')+p('系列ラベル付けでは各時刻のhから出力し、系列全体の分類では最後のhなどを使います。未来予測では未来の観測を入力へ混ぜません。生成時には一つ生成した出力を次の入力へ戻す場合があり、学習時に正解の直前トークンを渡すteacher forcingとの違いが生じます。')+p('RNN系は一定サイズの状態で逐次処理できる一方、時間方向の計算が前の状態に依存します。Transformerは過去の要素を直接参照でき、SSMは状態更新の構造を工夫する別の選択肢です。'))
 body+=refs([('LSTM 原論文（1997）','https://www.bioinf.jku.at/publications/older/2604.pdf'),('PyTorch：忘却ゲートを含む標準LSTMの式','https://docs.pytorch.org/docs/stable/generated/torch.nn.LSTM.html'),('GRU：Learning Phrase Representations（2014）','https://arxiv.org/abs/1406.1078')])
 page('rnn','RNN・LSTM・GRU — 状態を受け渡す','モデルの構造','MODEL 02 / RECURRENCE','過去を一定サイズの状態にまとめる。その情報をどれだけ残し、どれだけ書き換えるかを学びます。',body)
 transformer.build()
 vit.build()
 body=gnn_figures.content()
 body+=sec('outputs','表現から、三種類の予測へ',flow([('GNN層を反復','全ノードの表現',BLUE),('出力の集め方','1点 / 2点 / 全体'),('出力ヘッド','分類や回帰',ORANGE)],'同じGNNの表現を、異なるタスクの出力へ変える。')+bullets(['ノード分類：各ノードの特徴を分類器へ。例えば論文の研究分野。','リンク予測：二つのノード表現の内積やMLPから関係のスコアを作る。評価時に予測対象の辺を入力へ漏らさない。','グラフ全体の予測：全ノードの和・平均などのreadoutから分子の性質を予測する。'])+p('層を増やすと遠くまで届く一方、表現が似通うover-smoothingや、多数の遠方情報を小さなベクトルへ押し込むover-squashingが問題になります。ここで示した原型は結合の種類などの辺特徴をすべて直接使うわけではありません。分子では辺特徴や3Dの回転・並進の対称性を扱う拡張が重要です。'))
 body+=refs([('GCN：Kipf & Welling','https://arxiv.org/abs/1609.02907'),('GAT：Veličković et al.','https://arxiv.org/abs/1710.10903'),('GraphSAGE：Hamilton et al.','https://arxiv.org/abs/1706.02216'),('Message Passing Neural Networks','https://proceedings.mlr.press/v70/gilmer17a.html')])
 page('gnn','GNN — 関係を通して情報を集める','モデルの構造','MODEL 04 / GRAPH NEURAL NETWORKS','同じグラフでGCN・GAT・GraphSAGEを比較。近隣の選び方、重み付け、自己情報の混ぜ方を図と計算で追います。',body)
 ssm.build()
